<?php require __DIR__.'/includes/bootstrap.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf();$u=input($_POST,'username');$p=$_POST['password']??null;$answer=$_SESSION['captcha']??null;unset($_SESSION['captcha']);if($answer===null||!hash_equals((string)$answer,input($_POST,'captcha')))$error='Incorrect CAPTCHA.';elseif(!preg_match('/^[A-Za-z0-9_]{3,50}$/D',$u)||!is_string($p)||strlen($p)<8||strlen($p)>72||str_contains($p,"\0"))$error='Use 3–50 letters, numbers or underscores and a password of 8–72 bytes.';else{try{$s=$db->prepare('INSERT INTO movie_users (username,password) VALUES (?,?)');$s->execute([$u,password_hash($p,PASSWORD_DEFAULT)]);go('login.php');}catch(PDOException $e){if($e->getCode()!=='23000')throw $e;$error='Username unavailable.';}}}$a=random_int(2,19);$b=random_int(2,19);$_SESSION['captcha']=$a+$b;render('auth.twig',['error'=>$error,'question'=>"$a + $b",'register'=>true]);
